package vn.covie.checkout.persistence; import java.util.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import vn.covie.checkout.model.CheckoutSessionEntity; public interface CheckoutSessionRepository extends JpaRepository<CheckoutSessionEntity,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select s from CheckoutSessionEntity s where s.tokenHash=:hash")Optional<CheckoutSessionEntity> findByTokenHashForUpdate(@Param("hash")String hash);}
